// spec: arch
// Archaeology ч.1: поле раскопок, смерть блока, умения Enrage / Flurry / Quake (spec arch, правила 1–15).
import { power } from './num/gmlmath.mjs';

const table = (t) => t.rows.map((r) => Object.fromEntries(t.columns.map((c, i) => [c, r[i]])));

export function makeArchaeology(data) {
  const C = data.constants;
  const T = data.tables;
  const blocks = table(T.blocks);
  const waves = table(T.waves);
  const chanceSets = new Map(table(T.chanceSets).map((r) => [r.stage, [r.w0, r.w1, r.w2, r.w3, r.w4, r.w5, r.w6]]));
  const overrides = new Map(table(T.overrides).map((r) => [r.stage, r]));
  const patterns = new Map(table(T.patterns).map((r) => [r.stage, T.patterns.columns.slice(1).map((c) => r[c])]));
  const effects = table(T.effects);
  const upgrades = table(T.abilityUpgrades);
  const abilities = table(T.abilities);
  const N = C.slots;
  const tileChoices = Array.from({ length: C['tile.choices'] }, (_, i) => i);

  // шанс «a из b»: 2 слова, U mod ⌊b⌋, успех при (m + 1) − a ≤ 1e−5
  function chance(rng, a, b) {
    const U = rng.u63();
    const m = Number(U % BigInt(Math.floor(b)));
    return (m + 1) - a <= 1e-5;
  }

  function roundHp(x, obeliskLevel) {
    if (obeliskLevel > C['round.halfEvenObeliskMax']) return Math.floor(x + 0.5);
    const f = Math.floor(x);
    const d = x - f;
    if (d < 0.5) return f;
    if (d > 0.5) return f + 1;
    return f % 2 === 0 ? f : f + 1;
  }

  function xpForLevel(L) {
    return Math.ceil(C['xp.base'] * power(C['xp.growth'], L));
  }

  function tierOf(b, stage, ascension) {
    if (b === 0) return 1;
    const w = waves.find((r) => r.block === b);
    const cols = [w.tier2, w.tier3, w.tier4];
    const n = ascension >= C['tier.extraFromAscension'] ? 3 : 2;
    let tier = 1;
    for (let t = 0; t < n; t++) if (stage >= cols[t]) tier++;
    return tier;
  }

  function generateField({ stage, ascension, stats, cardEffects, obeliskLevel, chances }, rng) {
    let cur = chances.slice();
    if (chanceSets.has(stage)) cur = chanceSets.get(stage).slice();
    const ov = overrides.get(stage);
    const special = ov !== undefined && ascension >= ov.minAscension;
    const pattern = special && ov.block == null ? patterns.get(stage) : null;
    const f = {
      block: [], tier: [], hp: [], hpMax: [], armor: [], xp: [], fragmentRarity: [], fragments: [], effects: [], card: [], depleted: [], tile: [], gleaming: 0,
    };
    for (;;) {
      const gleaming = chance(rng, stats[C['stat.gleamChance']], C['gleam.die']) ? 1 : 0;
      const block = [], tile = [], eff = [];
      for (let i = 0; i < N; i++) {
        let b = 0;
        if (special) b = pattern ? pattern[i] : ov.block;
        else {
          for (let w = 0; w < waves.length; w++) {
            const wv = waves[w];
            if (stage >= wv.stage && ascension >= wv.ascension && chance(rng, C['spawn.chanceA'], cur[w])) b = wv.block;
          }
        }
        let tl = rng.choose(...tileChoices);
        if (chance(rng, C['spawn.chanceA'], C['tile.rareDie'])) tl = C['tile.rare'];
        if (b !== 0) tl = C['tile.block'];
        const e = [0, 0, 0, 0];
        if (b !== 0) {
          for (const ef of effects) {
            if (chance(rng, C['effect.scale'] * stats[ef.chanceStat], C['effect.die'])) e[ef.effect] = 1;
          }
        }
        block.push(b); tile.push(tl); eff.push(e);
      }
      if (block.some((b) => b !== 0)) {
        f.gleaming = gleaming;
        f.block = block; f.tile = tile; f.effects = eff;
        break;
      }
    }
    for (let i = 0; i < N; i++) {
      const b = f.block[i];
      const tier = tierOf(b, stage, ascension);
      f.tier.push(tier);
      if (b === 0) {
        f.card.push(0);
        f.hp.push(0); f.hpMax.push(0); f.armor.push(0); f.xp.push(0);
        f.fragmentRarity.push(-1); f.fragments.push(0); f.depleted.push(1);
        continue;
      }
      const card = tier === C['tier.cardTop'] ? C['card.topBase'] + b : C['card.perBlock'] * (b - 1) + tier - 1;
      const e = cardEffects[card];
      const row = blocks[b];
      let hp = row.maxHp * (1 - e);
      let xp = row.xp * stats[C['stat.expGain']] * (1 + e);
      if (f.effects[i][1]) xp *= stats[C['stat.expModGain']];
      let fr = row.fragments * stats[C['stat.fragmentGain']] * (1 + e);
      if (f.effects[i][2]) fr *= stats[C['stat.lootModGain']];
      const g = tier - 1;
      hp *= power(C['tier.hpGrowth'], g);
      let armor = row.armor * power(C['tier.armorGrowth'], g);
      xp *= power(C['tier.xpGrowth'], g);
      fr *= power(C['tier.fragmentGrowth'], g);
      for (let p = C['deep.from']; p <= C['deep.to']; p += C['deep.step']) {
        if (stage >= p) {
          hp *= C['deep.hp'];
          if (p !== C['deep.armorSkip']) armor *= C['deep.armor'];
        }
